class Solution:
    def majorityElement(self, nums: list[int]) -> int:
        return sorted(nums)[len(nums)//2]

solutions.optimal:
class Solution:
    def majorityElement(self, nums: list[int]) -> int:
        cand = None
        votes = 0
        for x in nums:
            if votes == 0:
                cand = x
            votes += 1 if x == cand else -1
        return cand

